        (True, None)
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': True, 'option2': True}
        """
        args = command_string.split()
        for arg in args:
            if arg.startswith('--'):
                arg_name = arg[2:]
                if arg_name in self.arguments:
                    self.arguments[arg_name] = True
                else:
                    self.required.add(arg_name)
            else:
                self.arguments[arg] = True
        return True, None if len(self.required) == 0 else list(self.required)

