    def check_left_bracket(self):
        """
        Checks if the expression has a left bracket.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_left_bracket()
        True

        """
        if self.expr[0] in self.left_brackets:
            self.stack.append(self.expr[0])
            self.expr = self.expr[1:]
        else:
            return False

    def check_right_bracket(self):
        """
        Checks if the expression has a right bracket.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_right_bracket()
        True

        """
        if self.expr[-1] in self.right_brackets:
            self.stack.append(self.expr[-1])
            self.expr = self.expr[:-1]
        else:
            return False

    def check_balanced_brackets_helper(self, expr):
        """
        Checks if the expression has balanced brackets.
        :param expr: The expression to check for balanced brackets,str.
        :return: True if the expression has balanced brackets,False otherwise.
        """
        if len(expr) == 0:
            return True
        if expr[0] in self.left_brackets:
            if self.stack.pop()!= expr[0]:
                return False
            else:
                return self.check_balanced_brackets_helper(expr[1:])
        elif expr[-1] in self.right_brackets:
            if self.stack.pop()!= expr[-1]:
                return False
            else:
                return self.check_balanced_brackets_helper(expr[:-1])
        else:
            return False

    def check_balanced_brackets(self):
        """
        Checks if the expression has balanced brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        True

        """
        self.clear_expr()
        return self.check_balanced_brackets_helper(self.expr)

