    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not textnum:
            return None
        if textnum.lower() in self.numwords:
            return self.numwords[textnum.lower()][0]
        if textnum.lower() in self.ordinal_words:
            return self.ordinal_words[textnum.lower()]
        if textnum.lower() in self.ordinal_endings:
            return self.ordinal_words[textnum.lower()[0]] + self.ordinal_endings[textnum.lower()[1]]
        if textnum.lower() in self.units:
            return self.numwords[textnum.lower()][0] * 100
        if textnum.lower() in self.tens:
